            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"55\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">YOUR BETTER NIGHT</text><text x=\"550\" y=\"100\" text-anchor=\"middle\" fill=\"#888\" font-size=\"23\">Six steps, starting tonight</text><rect x=\"150\" y=\"150\" width=\"800\" height=\"80\" rx=\"20\" fill=\"rgba(99,102,241,0.12)\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"200\" y=\"200\" text-anchor=\"start\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"20\">1.</text><text x=\"240\" y=\"200\" text-anchor=\"start\" fill=\"#fff\" font-size=\"18\">Anchor your wake time, 7 days a week</text><rect x=\"150\" y=\"260\" width=\"800\" height=\"80\" rx=\"20\" fill=\"rgba(139,92,246,0.12)\" stroke=\"#8b5cf6\" stroke-width=\"2\"/><text x=\"200\" y=\"310\" text-anchor=\"start\" fill=\"#8b5cf6\" font-weight=\"bold\" font-size=\"20\">2.</text><text x=\"240\" y=\"310\" text-anchor=\"start\" fill=\"#fff\" font-size=\"18\">Melatonin: 0.5-3 mg, USP Verified, timed</text><rect x=\"150\" y=\"370\" width=\"800\" height=\"80\" rx=\"20\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/><text x=\"200\" y=\"420\" text-anchor=\"start\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"20\">3.</text><text x=\"240\" y=\"420\" text-anchor=\"start\" fill=\"#fff\" font-size=\"18\">Lock gummies away from children</text><rect x=\"150\" y=\"480\" width=\"800\" height=\"80\" rx=\"20\" fill=\"rgba(245,158,11,0.12)\" stroke=\"#f59e0b\" stroke-width=\"2\"/><text x=\"200\" y=\"530\" text-anchor=\"start\" fill=\"#f59e0b\" font-weight=\"bold\" font-size=\"20\">4.</text><text x=\"240\" y=\"530\" text-anchor=\"start\" fill=\"#fff\" font-size=\"18\">Check interactions with your pharmacist</text><rect x=\"150\" y=\"590\" width=\"800\" height=\"80\" rx=\"20\" fill=\"rgba(236,72,153,0.1)\" stroke=\"#ec4899\" stroke-width=\"2\"/><text x=\"200\" y=\"640\" text-anchor=\"start\" fill=\"#ec4899\" font-weight=\"bold\" font-size=\"20\">5.</text><text x=\"240\" y=\"640\" text-anchor=\"start\" fill=\"#fff\" font-size=\"18\">Know the liver warning signs</text><rect x=\"150\" y=\"700\" width=\"800\" height=\"80\" rx=\"20\" fill=\"rgba(239,68,68,0.1)\" stroke=\"#ef4444\" stroke-width=\"2\"/><text x=\"200\" y=\"750\" text-anchor=\"start\" fill=\"#ef4444\" font-weight=\"bold\" font-size=\"20\">6.</text><text x=\"240\" y=\"750\" text-anchor=\"start\" fill=\"#fff\" font-size=\"18\">3+ months of poor sleep? Ask about CBT-I</text></svg>",
